// ContestDbContext contains raw file I/O methods bypassing EF Core:
public async Task<byte[]> ExportDatabaseAsync() {
    if (File.Exists("contest.db")) return await File.ReadAllBytesAsync("contest.db");
    return Array.Empty<byte>();
}
public async Task ImportDatabaseAsync(byte[] data) {
    await File.WriteAllBytesAsync("contest.db", data);
}

